package com.controldecortes.controller;
import com.controldecortes.dto.ApiDtos.*; import com.controldecortes.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/suppliers") public class SupplierController { private final SupplierService service; private final CutService cuts; public SupplierController(SupplierService s,CutService c){service=s;cuts=c;} @GetMapping public Object list(){return service.list();} @GetMapping("/{id}/cuts/active") public List<CutResponse> activeCuts(@PathVariable Long id){return cuts.activeBySupplier(id);} @PostMapping public ResponseEntity<SupplierResponse> create(@Valid @RequestBody SupplierRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PutMapping("/{id}") public SupplierResponse update(@PathVariable Long id,@Valid @RequestBody SupplierRequest r){return service.update(id,r);} @PatchMapping("/{id}/active") public SupplierResponse active(@PathVariable Long id,@RequestParam boolean value){return service.setActive(id,value);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
